"use client";

import { useState, useTransition } from "react";
import type { ReceiptSettings } from "@/lib/escpos";
import { saveReceiptSettings } from "./actions";

const DEFAULTS: Required<ReceiptSettings> = {
  show_address: false,
  show_phone: false,
  show_invoice: true,
  show_datetime: true,
  show_cashier: true,
  show_item_note: false,
  show_unit_price: true,
  show_item_disc: true,
  show_service: true,
  show_tax: true,
  show_payment_detail: true,
  footer_text: "Terima kasih!",
};

const TOGGLES: {
  key: Exclude<keyof Required<ReceiptSettings>, "footer_text">;
  label: string;
  desc?: string;
}[] = [
  { key: "show_address", label: "Alamat toko" },
  { key: "show_phone", label: "Nomor telepon toko" },
  { key: "show_invoice", label: "Nomor invoice" },
  { key: "show_datetime", label: "Tanggal & jam" },
  { key: "show_cashier", label: "Nama kasir" },
  {
    key: "show_item_note",
    label: "Catatan per item",
    desc: "Catatan khusus yang diinput kasir untuk item tertentu",
  },
  {
    key: "show_unit_price",
    label: "Harga satuan",
    desc: "Qty × harga di bawah nama produk",
  },
  { key: "show_item_disc", label: "Diskon item" },
  { key: "show_service", label: "Biaya layanan (service)" },
  { key: "show_tax", label: "Pajak (PPN)" },
  {
    key: "show_payment_detail",
    label: "Detail pembayaran",
    desc: "Metode, uang diterima, kembalian",
  },
];

function formatRp(n: number) {
  return `Rp${n.toLocaleString("id-ID")}`;
}

function ReceiptPreview({
  s,
  businessName,
  address,
  phone,
}: {
  s: Required<ReceiptSettings>;
  businessName: string;
  address: string | null;
  phone: string | null;
}) {
  const items = [
    { name: "Kopi Susu", qty: 2, price: 15000, note: "Less sweet", disc: 0 },
    { name: "Croissant", qty: 1, price: 22000, note: null, disc: 2200 },
  ];
  const subtotal = items.reduce((acc, i) => acc + i.qty * i.price, 0);
  const itemDisc = items.reduce((acc, i) => acc + i.disc, 0);
  const afterDisc = subtotal - itemDisc;
  const service = Math.round(afterDisc * 0.1);
  const tax = Math.round(afterDisc * 0.11);
  const total =
    afterDisc +
    (s.show_service ? service : 0) +
    (s.show_tax ? tax : 0);

  return (
    <div className="mx-auto w-48 rounded bg-white border border-zinc-200 p-3 font-mono text-[11px] text-zinc-800 shadow-sm">
      <div className="text-center">
        <p className="text-[12px] font-bold uppercase leading-tight">{businessName}</p>
        {s.show_address && address && (
          <p className="text-[10px] text-zinc-500">{address}</p>
        )}
        {s.show_phone && phone && (
          <p className="text-[10px] text-zinc-500">Tel: {phone}</p>
        )}
      </div>

      <div className="mt-1 border-t border-dashed border-zinc-300 pt-1 space-y-0.5">
        {s.show_invoice && (
          <div className="flex justify-between gap-1">
            <span>No.</span>
            <span>#INV-001</span>
          </div>
        )}
        {s.show_datetime && (
          <div className="flex justify-between gap-1">
            <span>Tgl</span>
            <span>02/08 12:00</span>
          </div>
        )}
        {s.show_cashier && (
          <div className="flex justify-between gap-1">
            <span>Kasir</span>
            <span>Andi</span>
          </div>
        )}
      </div>

      <div className="mt-1 border-t border-dashed border-zinc-300 pt-1 space-y-0.5">
        {items.map((item, i) => (
          <div key={i}>
            <div className="flex justify-between gap-1">
              <span className="flex-1 truncate">{item.name}</span>
              <span className="shrink-0">{formatRp(item.qty * item.price)}</span>
            </div>
            {s.show_unit_price && (
              <div className="text-[10px] text-zinc-400">
                {item.qty}×{formatRp(item.price)}
              </div>
            )}
            {s.show_item_note && item.note && (
              <div className="text-[10px] text-zinc-400 italic">* {item.note}</div>
            )}
          </div>
        ))}
      </div>

      <div className="mt-1 border-t border-dashed border-zinc-300 pt-1 space-y-0.5">
        <div className="flex justify-between gap-1">
          <span>Subtotal</span>
          <span>{formatRp(subtotal)}</span>
        </div>
        {s.show_item_disc && itemDisc > 0 && (
          <div className="flex justify-between gap-1 text-zinc-500">
            <span>Diskon item</span>
            <span>-{formatRp(itemDisc)}</span>
          </div>
        )}
        {s.show_service && (
          <div className="flex justify-between gap-1">
            <span>Layanan</span>
            <span>{formatRp(service)}</span>
          </div>
        )}
        {s.show_tax && (
          <div className="flex justify-between gap-1">
            <span>PPN</span>
            <span>{formatRp(tax)}</span>
          </div>
        )}
        <div className="flex justify-between gap-1 border-t border-dashed border-zinc-300 pt-0.5 font-bold">
          <span>TOTAL</span>
          <span>{formatRp(total)}</span>
        </div>
      </div>

      {s.show_payment_detail && (
        <div className="mt-1 border-t border-dashed border-zinc-300 pt-1 space-y-0.5">
          <div className="flex justify-between gap-1">
            <span>Tunai</span>
            <span>{formatRp(total + 5000)}</span>
          </div>
          <div className="flex justify-between gap-1">
            <span>Kembalian</span>
            <span>{formatRp(5000)}</span>
          </div>
        </div>
      )}

      <div className="mt-1 border-t border-dashed border-zinc-300 pt-1 text-center text-[10px]">
        {s.footer_text || "Terima kasih!"}
      </div>
    </div>
  );
}

export default function ReceiptSettingsSection({
  businessId,
  businessName,
  address,
  phone,
  initialSettings,
}: {
  businessId: string;
  businessName: string;
  address: string | null;
  phone: string | null;
  initialSettings: ReceiptSettings;
}) {
  const [s, setS] = useState<Required<ReceiptSettings>>({
    ...DEFAULTS,
    ...initialSettings,
  });
  const [isPending, startTransition] = useTransition();
  const [saved, setSaved] = useState(false);

  const toggle = (key: Exclude<keyof Required<ReceiptSettings>, "footer_text">) => {
    setS((prev) => ({ ...prev, [key]: !prev[key] }));
    setSaved(false);
  };

  const handleSave = () => {
    startTransition(async () => {
      await saveReceiptSettings(businessId, s as Record<string, unknown>);
      setSaved(true);
    });
  };

  return (
    <div className="mt-6 rounded-xl bg-white shadow-sm p-5">
      <h2 className="text-sm font-semibold text-zinc-900">Tampilan Struk</h2>
      <p className="mt-1 text-xs text-zinc-500">
        Pilih informasi yang ditampilkan di struk pelanggan.
      </p>

      <div className="mt-5 grid grid-cols-1 gap-6 md:grid-cols-2">
        {/* Checklist kiri */}
        <div className="space-y-3">
          {TOGGLES.map(({ key, label, desc }) => (
            <label key={key} className="flex cursor-pointer items-start gap-3 group">
              <input
                type="checkbox"
                checked={s[key]}
                onChange={() => toggle(key)}
                className="mt-0.5 h-4 w-4 shrink-0 rounded border-zinc-300 accent-brand-600"
              />
              <div>
                <span className="text-sm text-zinc-800 group-hover:text-zinc-900">{label}</span>
                {desc && <p className="text-[11px] text-zinc-400">{desc}</p>}
              </div>
            </label>
          ))}

          <div className="pt-2">
            <label className="block text-xs font-medium text-zinc-700 mb-1.5">
              Teks footer
            </label>
            <input
              type="text"
              value={s.footer_text}
              onChange={(e) => {
                setS((prev) => ({ ...prev, footer_text: e.target.value }));
                setSaved(false);
              }}
              placeholder="Terima kasih!"
              className="w-full rounded-lg border border-zinc-200 bg-white px-3 py-2 text-sm text-zinc-900 placeholder-zinc-400 focus:outline-none focus:ring-2 focus:ring-brand-300"
            />
          </div>

          <div className="pt-1">
            <button
              onClick={handleSave}
              disabled={isPending}
              className="rounded-lg bg-brand-600 px-4 py-2 text-sm font-medium text-white hover:bg-brand-700 disabled:opacity-50 transition-colors"
            >
              {isPending ? "Menyimpan…" : saved ? "Tersimpan ✓" : "Simpan pengaturan"}
            </button>
          </div>
        </div>

        {/* Preview kanan */}
        <div>
          <p className="mb-3 text-xs font-medium text-zinc-500">Preview struk</p>
          <ReceiptPreview
            s={s}
            businessName={businessName}
            address={address}
            phone={phone}
          />
          <p className="mt-2 text-center text-[10px] text-zinc-400">
            Data contoh — struk nyata menyesuaikan transaksi
          </p>
        </div>
      </div>
    </div>
  );
}

import { notFound } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import PrintButton from "./print-button";

function formatRupiah(value: number) {
  return `Rp${value.toLocaleString("id-ID")}`;
}

function formatDateTime(iso: string) {
  return new Date(iso).toLocaleString("id-ID", {
    dateStyle: "medium",
    timeStyle: "short",
  });
}

export default async function ReceiptPage({
  params,
}: {
  params: Promise<{ businessId: string; transactionId: string }>;
}) {
  const { businessId, transactionId } = await params;
  const supabase = await createClient();

  // Keempat query tidak saling bergantung (semua cuma butuh businessId/
  // transactionId dari params) — dijalankan paralel, bukan berurutan,
  // supaya struk render lebih cepat begitu dibuka dari POS.
  const [{ data: business }, { data: transaction }, { data: items }, { data: payments }, { data: printers }] =
    await Promise.all([
      supabase.from("businesses").select("name, address, phone, receipt_settings").eq("id", businessId).single(),
      supabase
        .from("transactions")
        .select(
          "id, invoice_number, date, subtotal_raw, subtotal, service, tax, total_item_disc, order_disc_amt, total, voided, cashiers!transactions_cashier_id_fkey(name)",
        )
        .eq("id", transactionId)
        .eq("business_id", businessId)
        .single(),
      supabase
        .from("transaction_items")
        .select("id, name, price, qty, note")
        .eq("transaction_id", transactionId)
        .order("id", { ascending: true }),
      supabase
        .from("transaction_payments")
        .select("id, method, amount, received, change")
        .eq("transaction_id", transactionId),
      supabase
        .from("kitchen_printers")
        .select("id, name")
        .eq("business_id", businessId)
        .order("name", { ascending: true }),
    ]);

  if (!business || !transaction) {
    notFound();
  }

  const rs = (business as unknown as { receipt_settings?: Record<string, unknown> }).receipt_settings ?? {};
  const cfg = {
    showAddress: (rs.show_address ?? false) as boolean,
    showPhone: (rs.show_phone ?? false) as boolean,
    showInvoice: (rs.show_invoice ?? true) as boolean,
    showDatetime: (rs.show_datetime ?? true) as boolean,
    showCashier: (rs.show_cashier ?? true) as boolean,
    showItemNote: (rs.show_item_note ?? false) as boolean,
    showUnitPrice: (rs.show_unit_price ?? true) as boolean,
    showItemDisc: (rs.show_item_disc ?? true) as boolean,
    showService: (rs.show_service ?? true) as boolean,
    showTax: (rs.show_tax ?? true) as boolean,
    showPaymentDetail: (rs.show_payment_detail ?? true) as boolean,
    footerText: (rs.footer_text as string | undefined) ?? "Terima kasih!",
  };
  const biz = business as unknown as { name: string; address?: string | null; phone?: string | null };

  return (
    <div className="w-full max-w-xs font-mono text-xs text-zinc-900 print:max-w-none">
        <div className="print:hidden">
          <PrintButton
            businessId={businessId}
            transactionId={transactionId}
            printers={printers ?? []}
          />
        </div>

        <div className="mt-4 rounded-xl bg-white shadow-sm p-5 print:mt-0 print:rounded-none print:border-0 print:p-0">
          <div className="text-center">
            <p className="text-sm font-bold uppercase">{biz.name}</p>
            {cfg.showAddress && biz.address && (
              <p className="text-[11px] text-zinc-500">{biz.address}</p>
            )}
            {cfg.showPhone && biz.phone && (
              <p className="text-[11px] text-zinc-500">Tel: {biz.phone}</p>
            )}
            {transaction.voided && (
              <p className="mt-1 font-bold text-red-600">*** DIBATALKAN ***</p>
            )}
          </div>

          <div className="mt-3 border-t border-dashed border-zinc-300 pt-2">
            {cfg.showInvoice && (
              <div className="flex justify-between">
                <span>No.</span>
                <span>{transaction.invoice_number}</span>
              </div>
            )}
            {cfg.showDatetime && (
              <div className="flex justify-between">
                <span>Tanggal</span>
                <span>{formatDateTime(transaction.date)}</span>
              </div>
            )}
            {cfg.showCashier && (
              <div className="flex justify-between">
                <span>Kasir</span>
                <span>
                  {(transaction.cashiers as unknown as { name: string } | null)?.name ?? "—"}
                </span>
              </div>
            )}
          </div>

          <div className="mt-2 space-y-1 border-t border-dashed border-zinc-300 pt-2">
            {items?.map((item) => (
              <div key={item.id}>
                <div className="flex justify-between gap-2">
                  <span className="flex-1 truncate">{item.name}</span>
                  <span className="shrink-0">
                    {formatRupiah(Number(item.price) * Number(item.qty))}
                  </span>
                </div>
                {cfg.showUnitPrice && (
                  <div className="text-zinc-400">
                    {item.qty}×{Number(item.price).toLocaleString("id-ID")}
                  </div>
                )}
                {cfg.showItemNote && (item as unknown as { note?: string | null }).note && (
                  <div className="text-zinc-400 italic">
                    * {(item as unknown as { note?: string | null }).note}
                  </div>
                )}
              </div>
            ))}
          </div>

          <div className="mt-2 space-y-1 border-t border-dashed border-zinc-300 pt-2">
            <div className="flex justify-between">
              <span>Subtotal</span>
              <span>{formatRupiah(Number(transaction.subtotal_raw))}</span>
            </div>
            {cfg.showItemDisc && Number(transaction.total_item_disc) > 0 && (
              <div className="flex justify-between">
                <span>Diskon item</span>
                <span>-{formatRupiah(Number(transaction.total_item_disc))}</span>
              </div>
            )}
            {Number(transaction.order_disc_amt) > 0 && (
              <div className="flex justify-between">
                <span>Diskon order</span>
                <span>-{formatRupiah(Number(transaction.order_disc_amt))}</span>
              </div>
            )}
            {cfg.showService && Number(transaction.service) > 0 && (
              <div className="flex justify-between">
                <span>Layanan</span>
                <span>{formatRupiah(Number(transaction.service))}</span>
              </div>
            )}
            {cfg.showTax && Number(transaction.tax) > 0 && (
              <div className="flex justify-between">
                <span>PPN</span>
                <span>{formatRupiah(Number(transaction.tax))}</span>
              </div>
            )}
            <div className="flex justify-between border-t border-dashed border-zinc-300 pt-1 text-sm font-bold">
              <span>TOTAL</span>
              <span>{formatRupiah(Number(transaction.total))}</span>
            </div>
          </div>

          {cfg.showPaymentDetail && (
            <div className="mt-2 space-y-1 border-t border-dashed border-zinc-300 pt-2">
              {payments?.map((p) => (
                <div key={p.id}>
                  <div className="flex justify-between">
                    <span>{p.method}</span>
                    <span>{formatRupiah(Number(p.amount))}</span>
                  </div>
                  {p.received !== null && (
                    <div className="flex justify-between">
                      <span>Diterima</span>
                      <span>{formatRupiah(Number(p.received))}</span>
                    </div>
                  )}
                  {p.change !== null && Number(p.change) > 0 && (
                    <div className="flex justify-between">
                      <span>Kembalian</span>
                      <span>{formatRupiah(Number(p.change))}</span>
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}

          <p className="mt-4 border-t border-dashed border-zinc-300 pt-2 text-center">
            {cfg.footerText || "Terima kasih!"}
          </p>
        </div>
    </div>
  );
}

