      p_customer_id: customerId,
      p_self_order_ids: selfOrderIds.length > 0 ? selfOrderIds : null,
      p_client_ref: clientRef,
    })
    .single();

  if (error || !data) {
    return { success: false, error: error?.message ?? "Gagal memproses transaksi." };
  }

