export async function saveReceiptSettings(
  businessId: string,
  settings: Record<string, unknown>,
): Promise<void> {
  const supabase = await createClient();
  await supabase
    .from("businesses")
    .update({ receipt_settings: settings })
    .eq("id", businessId);
  revalidatePath(`/business/${businessId}/settings`);
}

