  });

  it("ends with a partial-cut command", () => {
    const buf = buildKitchenTicket({ station: "Dapur", source: "Kasir", label: "INV-1", items: [] });
    expect(buf.subarray(buf.length - 4)).toEqual(Buffer.from([GS, 0x56, 0x42, 0x00]));
  });

