55	type BusinessType = "fnb" | "retail" | "tiket";
56	
57	function buildNavGroups(
58	  businessId: string,
59	  businessType: BusinessType,
60	  isFinanceOnly: boolean,
61	): NavGroup[] {
62	  const isFnb = businessType === "fnb";
63	  const base = `/business/${businessId}`;
64	
65	  return [
66	    {
67	      title: "Utama",
68	      items: [
69	        { key: "dashboard", href: base, label: "Dashboard", icon: LayoutDashboard },
70	        { key: "reports", href: `${base}/reports`, label: "Laporan", icon: BarChart3 },
71	        { key: "transactions", href: `${base}/transactions`, label: "Riwayat Transaksi", icon: Receipt },
72	        { key: "shifts", href: `${base}/shifts`, label: "Riwayat Shift", icon: Clock },
73	        { key: "kas-harian", href: `${base}/kas-harian`, label: "Kas Harian", icon: Wallet },
74	        { key: "products", href: `${base}/products`, label: "Kelola Produk", icon: Package },
75	        ...(isFnb
76	          ? [
77	              { key: "ingredients", href: `${base}/ingredients`, label: "Bahan Baku", icon: Beaker },
78	              {
79	                key: "tables",
80	                href: `${base}/tables`,
81	                label: "Meja & Self-Order",
82	                icon: UtensilsCrossed,
83	              },
84	            ]
85	          : []),
86	        ...(isFinanceOnly
87	          ? []
88	          : [
89	              { key: "customers", href: `${base}/customers`, label: "Pelanggan", icon: Users },
90	              { key: "cashiers", href: `${base}/cashiers`, label: "Kelola Kasir", icon: UserCheck },
91	            ]),
92	        { key: "settings", href: `${base}/settings`, label: "Pengaturan", icon: Settings, ownerOnly: true },
93	        { key: "admins", href: `${base}/admins`, label: "Kelola Admin", icon: ShieldCheck, ownerOnly: true },
94	      ],
95	    },
96	    {
97	      title: "Fitur Lanjutan",
98	      items: [
99	        { key: "reports-laba-rugi", href: `${base}/reports/laba-rugi`, label: "Laba Rugi", icon: TrendingUp },
100	        { key: "reports-cogs", href: `${base}/reports/cogs`, label: "Laporan COGS", icon: Ruler },
101	        { key: "hpp-calculator", href: `${base}/hpp-calculator`, label: "Kalkulator HPP", icon: Calculator },
102	        ...(isFnb
103	          ? [{ key: "reports-price-trend", href: `${base}/reports/price-trend`, label: "Tren Harga", icon: Tag }]
104	          : []),
105	        { key: "accounting-daftar-akun", href: `${base}/accounting/daftar-akun`, label: "Daftar Akun", icon: BookOpen },
106	        {
107	          key: "accounting-laba-rugi",
108	          href: `${base}/accounting/laba-rugi`,
109	          label: "Laba Rugi (Akrual)",
110	          icon: TrendingUp,
111	        },
112	        { key: "accounting-jurnal", href: `${base}/accounting/jurnal`, label: "Jurnal Transaksi", icon: FileText },
113	        { key: "accounting-neraca", href: `${base}/accounting/neraca`, label: "Neraca", icon: Scale },
114	        { key: "accounting-arus-kas", href: `${base}/accounting/arus-kas`, label: "Arus Kas", icon: RefreshCw },
115	        { key: "accounting-anggaran", href: `${base}/accounting/anggaran`, label: "Target vs Aktual", icon: Target },
116	        { key: "accounting-modal", href: `${base}/accounting/modal`, label: "Perubahan Modal", icon: ScrollText },
117	        {
118	          key: "accounting-transfer-kas",
119	          href: `${base}/accounting/transfer-kas`,
120	          label: "Transfer Kas/Bank",
121	          icon: ArrowLeftRight,
122	        },
123	        {
124	          key: "accounting-rekonsiliasi",
125	          href: `${base}/accounting/rekonsiliasi`,
126	          label: "Rekonsiliasi Rekening",
127	          icon: Landmark,
128	        },
129	        { key: "invoices", href: `${base}/invoices`, label: "Invoice/Nota", icon: Receipt },
130	        { key: "accounting-tutup-buku", href: `${base}/accounting/tutup-buku`, label: "Tutup Buku", icon: Lock },
131	        ...(isFinanceOnly
132	          ? []
133	          : [
134	              { key: "receivables", href: `${base}/receivables`, label: "Piutang Pelanggan", icon: CreditCard },
135	              { key: "purchases", href: `${base}/purchases`, label: "Pembelian & Hutang", icon: ShoppingBag },
136	              { key: "suppliers", href: `${base}/suppliers`, label: "Supplier", icon: Store },
137	              { key: "assets", href: `${base}/assets`, label: "Aset Tetap", icon: Monitor },
138	            ]),
139	        { key: "employees", href: `${base}/employees`, label: "Karyawan", icon: UserCog },
140	        { key: "attendance", href: `${base}/attendance`, label: "Absensi", icon: CalendarCheck },
141	        { key: "payroll", href: `${base}/payroll`, label: "Payroll", icon: Banknote },
142	      ],
143	    },
144	    {
145	      title: "Lainnya",
146	      items: [
147	        { key: "notifikasi", href: `${base}/notifikasi`, label: "Notifikasi", icon: Bell },
148	        { key: "activity", href: `${base}/activity`, label: "Aktivitas", icon: Activity },
149	      ],
150	    },
151	  ];
152	}
153	
154	// Dashboard itself is always reachable even for a staff member with an empty
155	// checklist — a completely inaccessible landing page would make no sense.
156	// bypassOwnerOnly exists only for the Android app's native-mode override
157	// below — real business_staff permission checks never pass it, so ownerOnly
158	// keeps its original strict meaning ("never grantable via the checklist")
159	// for actual staff accounts.
160	function isItemAllowed(
161	  item: NavItem,
162	  isOwner: boolean,
163	  permissions: string[],
164	  bypassOwnerOnly: string[] = [],
165	): boolean {
166	  if (isOwner) return true;
167	  if (item.ownerOnly && !bypassOwnerOnly.includes(item.key)) return false;
168	  if (item.key === "dashboard") return true;
169	  return permissions.includes(item.key);
170	}
171	
172	function filterGroupsForPermissions(
173	  groups: NavGroup[],
174	  isOwner: boolean,
175	  permissions: string[],
176	  bypassOwnerOnly: string[] = [],
177	): NavGroup[] {
178	  if (isOwner) return groups;
179	  return groups
180	    .map((g) => ({
181	      ...g,
182	      items: g.items.filter((i) => isItemAllowed(i, isOwner, permissions, bypassOwnerOnly)),
183	    }))
184	    .filter((g) => g.items.length > 0);
185	}
186	
187	const BUSINESS_TYPE_SUBTITLE: Record<string, string> = {
188	  fnb: "Restoran / Kafe / F&B",
189	  retail: "Retail / Toko",
190	  tiket: "Tempat Wisata / Tiket",
191	};
192	
193	function findActiveItem(groups: NavGroup[], pathname: string): NavItem | null {
194	  const allItems = groups.flatMap((g) => g.items);
195	  const matches = allItems.filter((i) => pathname === i.href || pathname.startsWith(`${i.href}/`));
196	  if (matches.length === 0) return null;
197	  return matches.sort((a, b) => b.href.length - a.href.length)[0];
198	}
199	
200	function activeGroupTitleOf(groups: NavGroup[], activeHref: string | null): string | null {
201	  if (!activeHref) return groups[0]?.title ?? null;
202	  return groups.find((g) => g.items.some((i) => i.href === activeHref))?.title ?? groups[0]?.title ?? null;
203	}
204	
205	// Feedback instan begitu link nav ditekan — tanpa ini, halaman SEBELUMNYA
206	// tetap nempel di layar sampai halaman baru selesai fetch data (bisa
207	// beberapa detik di jaringan mobile), kelihatan seperti "salah pindah
208	// halaman". Sengaja pakai useLinkStatus (murni client-side, tidak ada file
209	// baru di app/) alih-alih loading.tsx — file itu terbukti bikin SEMUA rute
210	// 404 di versi Next.js proyek ini (dicoba 2x, di root grup & per-halaman).
211	// Harus jadi child terpisah dari <Link>, useLinkStatus tidak bisa dipanggil
212	// di komponen yang sama dengan <Link>-nya.
213	function NavPendingHint() {
214	  const { pending } = useLinkStatus();
215	  return (
216	    <span
217	      aria-hidden="true"
218	      className={`ml-auto h-3 w-3 shrink-0 rounded-full border-2 border-zinc-200 border-t-brand-600 transition-opacity ${
219	        pending ? "animate-spin opacity-100" : "opacity-0"
220	      }`}
221	    />
222	  );
223	}
224	
225	function SidebarContent({
226	  businessId,
227	  businessName,
228	  businessType,
229	  groups,
230	  activeHref,
231	  isFinanceOnly,
232	  onNavigate,
233	  showLogout = true,
234	}: {
235	  businessId: string;
236	  businessName: string;
237	  businessType: BusinessType;
238	  groups: NavGroup[];
239	  activeHref: string | null;
240	  isFinanceOnly: boolean;
241	  onNavigate?: () => void;
242	  showLogout?: boolean;
243	}) {
244	  const activeGroupTitle = activeGroupTitleOf(groups, activeHref);
245	  const [openGroup, setOpenGroup] = useState<string | null>(activeGroupTitle);
246	
247	  // Setelah navigasi ke halaman baru, buka grup yang memuat halaman itu —
248	  // supaya sidebar selalu menunjukkan konteks tanpa perlu klik manual. Disesuaikan
249	  // saat render (bukan di useEffect) supaya tetap bisa di-override oleh klik manual.
250	  const [prevActiveGroupTitle, setPrevActiveGroupTitle] = useState(activeGroupTitle);
251	  if (activeGroupTitle !== prevActiveGroupTitle) {
252	    setPrevActiveGroupTitle(activeGroupTitle);
253	    setOpenGroup(activeGroupTitle);
254	  }
255	
256	  return (
257	    <div className="flex h-full flex-col bg-white">
258	      <div className="flex items-center gap-2.5 border-b border-zinc-100 px-5 py-5">
259	        <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-brand-600">
260	          <span className="text-sm font-bold text-white">K</span>
261	        </div>
262	        <div className="min-w-0">
263	          <p className="truncate text-sm font-bold text-zinc-800">{businessName}</p>
264	          <p className="text-[11px] text-zinc-400">{BUSINESS_TYPE_SUBTITLE[businessType]}</p>
265	        </div>
266	      </div>
267	
268	      {!isFinanceOnly && (
269	        <div className="px-3 pt-4">
270	          <Link
271	            href={`/business/${businessId}/pos`}
272	            onClick={onNavigate}
273	            className="flex items-center justify-center gap-1.5 rounded-xl bg-brand-600 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-brand-700"
274	          >
275	            <ShoppingCart className="h-4 w-4" aria-hidden="true" />
276	            Buka Kasir
277	          </Link>
278	        </div>
279	      )}
280	
281	      <nav className="flex-1 space-y-1 overflow-y-auto px-3 py-4">
282	        {groups.map((group) => {
283	          const isOpen = openGroup === group.title;
284	          return (
285	            <div key={group.title}>
286	              <button
287	                type="button"
288	                onClick={() => setOpenGroup((g) => (g === group.title ? null : group.title))}
289	                className="flex w-full items-center justify-between rounded-lg px-2 py-2 text-[10.5px] font-semibold uppercase tracking-wide text-zinc-400 transition-colors hover:bg-zinc-50 hover:text-zinc-600"
290	              >
291	                <span>{group.title}</span>
292	                <ChevronRight
293	                  className={`h-3.5 w-3.5 transition-transform duration-150 ${isOpen ? "rotate-90" : ""}`}
294	                  aria-hidden="true"
295	                />
296	              </button>
297	              {isOpen && (
298	                <div className="mt-0.5 space-y-0.5 pb-1">
299	                  {group.items.map((item) => {
300	                    const Icon = item.icon;
301	                    const isActive = activeHref === item.href;
302	                    return (
303	                      <Link
304	                        key={item.href}
305	                        href={item.href}
306	                        onClick={onNavigate}
307	                        className={`flex items-center gap-2.5 rounded-lg px-2.5 py-2 text-[13px] font-medium transition-colors ${
308	                          isActive
309	                            ? "bg-brand-50 text-brand-700"
310	                            : "text-zinc-600 hover:bg-zinc-50"
311	                        }`}
312	                      >
313	                        <Icon
314	                          className={`h-[18px] w-[18px] shrink-0 ${
315	                            isActive ? "text-brand-600" : "text-zinc-400"
316	                          }`}
317	                          strokeWidth={isActive ? 2.25 : 1.75}
318	                          aria-hidden="true"
319	                        />
320	                        {item.label}
321	                        <NavPendingHint />
322	                      </Link>
323	                    );
324	                  })}
325	                </div>
326	              )}
327	            </div>
328	          );
329	        })}
330	      </nav>
331	
332	      <div className="border-t border-zinc-100 px-3 py-3">
333	        <Link
334	          href="/dashboard"
335	          onClick={onNavigate}
336	          className="mb-1 block rounded-lg px-2.5 py-2 text-[13px] font-medium text-zinc-500 hover:bg-zinc-50"
337	        >
338	          ← Semua Toko
339	        </Link>
340	        {showLogout && <LogoutButton />}
341	      </div>
342	    </div>
343	  );
344	}
345	
346	function Topbar({ businessName, userEmail }: { businessName: string; userEmail: string }) {
347	  const today = new Date().toLocaleDateString("id-ID", {
348	    weekday: "long",
349	    day: "numeric",
350	    month: "long",
351	    year: "numeric",
352	  });
353	  const initial = (userEmail || businessName).charAt(0).toUpperCase();
354	
355	  return (
356	    <div className="sticky top-0 z-10 hidden items-center justify-between bg-white px-8 py-4 shadow-[0_1px_3px_rgba(0,0,0,0.06)] md:flex print:hidden">
357	      <div>
358	        <p className="text-sm font-bold text-zinc-800">{businessName}</p>
359	        <p className="text-[11.5px] text-zinc-400">{today}</p>
360	      </div>
361	      <div className="flex items-center gap-3">
362	        <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-brand-100 text-xs font-bold text-brand-700">
363	          {initial}
364	        </div>
365	        {userEmail && <p className="max-w-[180px] truncate text-sm text-zinc-600">{userEmail}</p>}
366	        <LogoutButton variant="inline" />
367	      </div>
368	    </div>
369	  );
370	}
371	
372	function AccessDeniedPanel() {
373	  return (
374	    <div className="flex min-h-[40vh] flex-col items-center justify-center rounded-xl bg-white p-8 text-center shadow-sm">
375	      <div className="mb-3 flex h-12 w-12 items-center justify-center rounded-full bg-red-50 text-2xl">
376	        🔒
377	      </div>
378	      <h1 className="text-lg font-bold text-zinc-900">Akses Ditolak</h1>
379	      <p className="mt-1 max-w-sm text-sm text-zinc-500">
380	        Kamu tidak punya izin untuk membuka halaman ini. Hubungi pemilik toko kalau merasa ini
381	        seharusnya bisa diakses.
382	      </p>
383	    </div>
384	  );
385	}
386	
387	export default function DashboardShell({
388	  businessId,
389	  businessName,
390	  businessType,
391	  userEmail,
392	  billingPastDuePeriodEnd,
393	  trialPeriodEnd,
394	  isFinanceOnly = false,
395	  isOwner = true,
396	  permissions = [],
397	  children,
398	}: {
399	  businessId: string;
400	  businessName: string;
401	  businessType: BusinessType;
402	  userEmail: string;
403	  billingPastDuePeriodEnd?: string | null;
404	  trialPeriodEnd?: string | null;
405	  isFinanceOnly?: boolean;
406	  isOwner?: boolean;
407	  permissions?: string[];
408	  children: React.ReactNode;
409	}) {
410	  const pathname = usePathname();
411	  const [mobileNavOpen, setMobileNavOpen] = useState(false);
412	
413	  // The Android app (android-app/) is a cashier tool, not a backoffice one —
414	  // mirrors Moka's own "Cashier: App Only" vs "Administrator: App & Back-
415	  // office" split. Whoever is logged in (owner or staff), the native app
416	  // only ever gets Aktivitas (transactions) + Riwayat Shift + Pengaturan
417	  // here; everything else in this sidebar stays desktop-browser-only.
418	  // Pengaturan is included specifically because Tambah Printer lives there
419	  // (pos/printers is view+test only, adding/editing a printer still needs
420	  // the full Settings form) — bypassOwnerOnly is what lets a normally
421	  // owner-only item through despite navIsOwner being forced false.
422	  const isNative = Capacitor.isNativePlatform();
423	  const navIsOwner = isNative ? false : isOwner;
424	  const navPermissions = isNative ? ["transactions", "shifts", "settings"] : permissions;
425	  const navBypassOwnerOnly = isNative ? ["settings"] : [];
426	
427	  const allGroups = buildNavGroups(businessId, businessType, isFinanceOnly);
428	  const visibleGroups = filterGroupsForPermissions(allGroups, navIsOwner, navPermissions, navBypassOwnerOnly);
429	  // Active item is resolved against the FULL (unfiltered) list — a page a
430	  // staff member isn't allowed to see should still be recognized so we can
431	  // show "Akses Ditolak" instead of silently rendering nothing/wrong content.
432	  const activeItem = findActiveItem(allGroups, pathname);
433	  const activeHref = activeItem?.href ?? null;
434	  const isAllowed = activeItem
435	    ? isItemAllowed(activeItem, navIsOwner, navPermissions, navBypassOwnerOnly)
436	    : navIsOwner;
437	
438	  return (
439	    <div className="flex min-h-screen w-full bg-[#F4F6F9] print:bg-white">
440	      {/* Sidebar tetap — desktop */}
441	      <aside className="hidden w-64 shrink-0 bg-white shadow-[1px_0_3px_rgba(0,0,0,0.04)] md:block print:hidden">
442	        <div className="sticky top-0 h-screen">
443	          <SidebarContent
444	            businessId={businessId}
445	            businessName={businessName}
446	            businessType={businessType}
447	            groups={visibleGroups}
448	            activeHref={activeHref}
449	            isFinanceOnly={isFinanceOnly}
450	            showLogout={false}
451	          />
452	        </div>
453	      </aside>
454	
455	      {/* Sidebar drawer — mobile */}
456	      {mobileNavOpen && (
457	        <div className="fixed inset-0 z-50 md:hidden">
458	          <div
459	            className="absolute inset-0 bg-black/40"
460	            onClick={() => setMobileNavOpen(false)}
461	          />
462	          <div className="absolute inset-y-0 left-0 w-72 bg-white shadow-xl">
463	            <SidebarContent
464	              businessId={businessId}
465	              businessName={businessName}
466	              businessType={businessType}
467	              groups={visibleGroups}
468	              activeHref={activeHref}
469	              isFinanceOnly={isFinanceOnly}
470	              onNavigate={() => setMobileNavOpen(false)}
471	            />
472	          </div>
473	        </div>
474	      )}
475	
476	      <div className="min-w-0 flex-1">
477	        <Topbar businessName={businessName} userEmail={userEmail} />
478	
479	        <div className="flex items-center gap-3 bg-white px-4 py-3 shadow-[0_1px_3px_rgba(0,0,0,0.06)] md:hidden print:hidden">
480	          <button
481	            onClick={() => setMobileNavOpen(true)}
482	            className="flex h-9 w-9 items-center justify-center rounded-lg border border-zinc-200 text-zinc-600"
483	            aria-label="Buka menu"
484	          >
485	            ☰
486	          </button>
487	          <p className="truncate text-sm font-bold text-zinc-800">{businessName}</p>
488	        </div>
489	
490	        {isOwner && trialPeriodEnd && (
491	          <div className="flex items-center justify-between gap-3 bg-brand-50 px-4 py-2.5 text-xs font-medium text-brand-800 print:hidden md:px-8">
492	            <span>
493	              Uji coba gratis berakhir{" "}
494	              {Math.max(
495	                0,
496	                Math.ceil(
497	                  (new Date(trialPeriodEnd).getTime() - new Date().getTime()) /
498	                    (24 * 60 * 60 * 1000),
499	                ),
500	              )}{" "}
501	              hari lagi — berlangganan sekarang supaya akses tidak terputus.
502	            </span>
503	            <Link
504	              href={`/business/${businessId}/billing`}
505	              className="shrink-0 rounded-full bg-brand-600 px-3 py-1 text-white hover:bg-brand-700"
506	            >
507	              Berlangganan
508	            </Link>
509	          </div>
510	        )}
511	
512	        {isOwner && billingPastDuePeriodEnd && (
513	          <div className="flex items-center justify-between gap-3 bg-amber-50 px-4 py-2.5 text-xs font-medium text-amber-800 print:hidden md:px-8">
514	            <span>
515	              Langganan jatuh tempo sejak{" "}
516	              {new Date(billingPastDuePeriodEnd).toLocaleDateString("id-ID", {
517	                day: "2-digit",
518	                month: "long",
519	                year: "numeric",
520	              })}
521	              — bayar sebelum masa tenggang habis agar akses tidak terkunci.
522	            </span>
523	            <Link
524	              href={`/business/${businessId}/billing`}
525	              className="shrink-0 rounded-full bg-amber-600 px-3 py-1 text-white hover:bg-amber-700"
526	            >
527	              Bayar Sekarang
528	            </Link>
529	          </div>
530	        )}
531	
532	        <main className="w-full px-4 py-8 md:px-8 md:py-10 print:p-0">
533	          <div className="mx-auto w-full max-w-6xl print:max-w-none">
534	            {isAllowed ? children : <AccessDeniedPanel />}
535	          </div>
536	        </main>
537	      </div>
538	    </div>
539	  );
540	}
