  bypassOwnerOnly: string[] = [],
  isStarter = false,
): NavGroup[] {
  if (isOwner && !isStarter) return groups;
  return groups
    .map((g) => ({
      ...g,
      items: g.items.filter((i) => isItemAllowed(i, isOwner, permissions, bypassOwnerOnly, isStarter)),
    }))
    .filter((g) => g.items.length > 0);
}

