"use client";

import { useRef, useState } from "react";
import Link from "next/link";
import { trackEvent } from "@/lib/analytics/google-analytics";
import { DesktopAppPreview } from "./desktop-app-preview";

type Ingredient = { id: string; name: string; cost: string };

function formatRupiah(value: number) {
  if (!Number.isFinite(value)) return "Rp0";
  return `Rp${Math.round(value).toLocaleString("id-ID")}`;
}

function makeIngredient(name = "", cost = ""): Ingredient {
  return { id: crypto.randomUUID(), name, cost };
}

export function HppCalculator() {
  const [ingredients, setIngredients] = useState<Ingredient[]>(() => [
    makeIngredient("Nasi 1 porsi", "2500"),
    makeIngredient("Telur 1 butir", "2000"),
    makeIngredient("Ayam suwir 50gr", "4000"),
    makeIngredient("Bumbu & minyak", "1500"),
  ]);
  const [portions, setPortions] = useState("1");
  const [marginPercent, setMarginPercent] = useState("60");
  const trackedRef = useRef(false);

  const totalCost = ingredients.reduce((sum, ing) => sum + (parseFloat(ing.cost) || 0), 0);
  const portionCount = Math.max(parseFloat(portions) || 1, 1);
  const hppPerPortion = totalCost / portionCount;
  const margin = Math.min(Math.max(parseFloat(marginPercent) || 0, 0), 95);
  const suggestedPrice = hppPerPortion / (1 - margin / 100);
  const grossProfit = suggestedPrice - hppPerPortion;

  function trackFirstUse() {
    if (!trackedRef.current) {
      trackedRef.current = true;
      trackEvent("hpp_calculator_used");
    }
  }

  function updateIngredient(id: string, field: "name" | "cost", value: string) {
    trackFirstUse();
    setIngredients((prev) => prev.map((ing) => (ing.id === id ? { ...ing, [field]: value } : ing)));
  }

  function addIngredient() {
    trackFirstUse();
    setIngredients((prev) => [...prev, makeIngredient()]);
  }

  function removeIngredient(id: string) {
    setIngredients((prev) => prev.filter((ing) => ing.id !== id));
  }

  return (
    <div className="grid gap-6 lg:grid-cols-5">
      <div className="rounded-2xl border border-zinc-200 bg-white p-6 shadow-sm lg:col-span-3">
        <p className="text-sm font-bold text-zinc-900">Bahan & Biaya per Porsi</p>
        <div className="mt-4 space-y-2">
          {ingredients.map((ing) => (
            <div key={ing.id} className="flex items-center gap-2">
              <input
                type="text"
                value={ing.name}
                onChange={(e) => updateIngredient(ing.id, "name", e.target.value)}
                placeholder="Nama bahan"
                className="flex-1 rounded-lg border border-zinc-200 px-3 py-2 text-sm focus:border-brand-500 focus:outline-none"
              />
              <input
                type="number"
                inputMode="numeric"
                value={ing.cost}
                onChange={(e) => updateIngredient(ing.id, "cost", e.target.value)}
                placeholder="Biaya (Rp)"
                className="w-28 rounded-lg border border-zinc-200 px-3 py-2 text-sm focus:border-brand-500 focus:outline-none sm:w-32"
              />
              <button
                type="button"
                onClick={() => removeIngredient(ing.id)}
                className="shrink-0 rounded-lg px-2 py-2 text-zinc-400 transition-colors hover:bg-zinc-50 hover:text-red-500"
                aria-label="Hapus bahan"
              >
                ✕
              </button>
            </div>
          ))}
        </div>
        <button
          type="button"
          onClick={addIngredient}
          className="mt-3 text-xs font-semibold text-brand-700 hover:underline"
        >
          + Tambah Bahan
        </button>

        <div className="mt-6 grid grid-cols-2 gap-4 border-t border-zinc-100 pt-6">
          <div>
            <label className="text-xs font-semibold text-zinc-500">Jumlah Porsi Dihasilkan</label>
            <input
              type="number"
              inputMode="numeric"
              min="1"
              value={portions}
              onChange={(e) => {
                trackFirstUse();
                setPortions(e.target.value);
              }}
              className="mt-1 w-full rounded-lg border border-zinc-200 px-3 py-2 text-sm focus:border-brand-500 focus:outline-none"
            />
          </div>
          <div>
            <label className="text-xs font-semibold text-zinc-500">Target Margin Kotor (%)</label>
            <input
              type="number"
              inputMode="numeric"
              min="0"
              max="95"
              value={marginPercent}
              onChange={(e) => {
                trackFirstUse();
                setMarginPercent(e.target.value);
              }}
              className="mt-1 w-full rounded-lg border border-zinc-200 px-3 py-2 text-sm focus:border-brand-500 focus:outline-none"
            />
          </div>
        </div>
      </div>

      <div className="space-y-3 lg:col-span-2">
        <div className="rounded-2xl bg-zinc-900 p-6 text-white shadow-lg">
          <p className="text-xs font-semibold uppercase tracking-wide text-zinc-400">HPP per Porsi</p>
          <p className="mt-1 text-3xl font-bold">{formatRupiah(hppPerPortion)}</p>
          <p className="mt-1 text-xs text-zinc-400">Total biaya bahan: {formatRupiah(totalCost)}</p>
        </div>

        <div className="rounded-2xl border-2 border-brand-500 bg-brand-50 p-6">
          <p className="text-xs font-semibold uppercase tracking-wide text-brand-700">
            Harga Jual Disarankan
          </p>
          <p className="mt-1 text-3xl font-bold text-brand-700">{formatRupiah(suggestedPrice)}</p>
          <p className="mt-1 text-xs text-brand-600">
            Margin kotor: {formatRupiah(grossProfit)} ({margin}%)
          </p>
        </div>

        {/* Desktop app — tampil di tengah supaya kelihatan */}
        <div className="rounded-2xl border border-zinc-200 bg-white p-5 shadow-sm">
          <div className="flex items-start justify-between gap-3">
            <div>
              <p className="text-sm font-bold text-zinc-900">Cuma Butuh Kalkulator HPP-nya Saja?</p>
              <p className="mt-1 text-xs leading-relaxed text-zinc-500">
                Versi aplikasi desktop Windows — sekali beli, data tersimpan di komputer, tanpa perlu daftar kasir.
              </p>
            </div>
            <div className="shrink-0 text-right">
              <p className="text-lg font-bold text-brand-700">Rp69.000</p>
              <p className="text-[10px] text-zinc-400">Sekali bayar</p>
            </div>
          </div>
          <Link
            href="/kalkulator-hpp/beli"
            onClick={() => trackEvent("hpp_calculator_desktop_cta_click")}
            className="mt-4 block rounded-xl border border-brand-200 py-2.5 text-center text-sm font-semibold text-brand-700 transition-colors hover:bg-brand-50"
          >
            💻 Lihat Aplikasi Desktop
          </Link>
        </div>

        <div className="rounded-2xl bg-gradient-to-br from-brand-700 via-brand-600 to-emerald-600 p-6 text-white shadow-lg">
          <p className="text-sm font-bold">Capek Hitung Ulang Tiap Harga Bahan Naik?</p>
          <p className="mt-1.5 text-xs leading-relaxed text-brand-50/90">
            KasirKu menghitung HPP setiap produk otomatis dari resepnya — begitu harga satu bahan
            berubah, semua produk yang memakainya ikut ter-update sendiri.
          </p>
          <Link
            href="/signup"
            onClick={() => trackEvent("hpp_calculator_cta_click")}
            className="mt-4 inline-block rounded-xl bg-white px-5 py-2.5 text-sm font-semibold text-brand-700 shadow-md transition-colors hover:bg-brand-50"
          >
            Coba KasirKu Gratis →
          </Link>
        </div>
      </div>
    </div>
  );
}

// Not DB-driven on purpose: fastest to ship, revisit if pricing needs to
// change without a deploy. ALL prices are FINAL (set by Melan 2026-07-17).
export type PlanCode = "monthly" | "yearly" | "lifetime" | "finance_monthly" | "finance_yearly" | "starter_monthly" | "starter_yearly";

// "full"    = Kasir/POS + Akuntansi + SDM bundled (the original product).
// "finance" = Akuntansi/SDM only, for businesses that already have their own
//             POS and don't need (or shouldn't see) the Operasional nav.
// "starter" = POS + COGS/Bahan Baku + Laporan Penjualan only (low-budget).
export type PlanFamily = "full" | "finance" | "starter";

export type Plan = {
  code: PlanCode;
  name: string;
  kind: "subscription" | "lifetime";
  periodDays: number | null; // null = lifetime, never expires
  price: number;
  family: PlanFamily;
};

export const PLANS: Plan[] = [
  { code: "monthly", name: "Langganan Bulanan", kind: "subscription", periodDays: 30, price: 299000, family: "full" },
  { code: "yearly", name: "Langganan Tahunan", kind: "subscription", periodDays: 365, price: 2490000, family: "full" },
  { code: "lifetime", name: "Sekali Bayar (Lifetime)", kind: "lifetime", periodDays: null, price: 766000, family: "full" },
  { code: "finance_monthly", name: "Finance Only — Bulanan", kind: "subscription", periodDays: 30, price: 149000, family: "finance" },
  { code: "finance_yearly", name: "Finance Only — Tahunan", kind: "subscription", periodDays: 365, price: 1299000, family: "finance" },
  { code: "starter_monthly", name: "Starter — Bulanan", kind: "subscription", periodDays: 30, price: 88000, family: "starter" },
  { code: "starter_yearly", name: "Starter — Tahunan", kind: "subscription", periodDays: 365, price: 799000, family: "starter" },
];

export function getPlan(code: string): Plan | undefined {
  return PLANS.find((p) => p.code === code);
}

export function isFinancePlan(code: string | null): boolean {
  if (!code) return false;
  return getPlan(code)?.family === "finance";
}

export function isStarterPlan(code: string | null): boolean {
  if (!code) return false;
  return getPlan(code)?.family === "starter";
}

import { notFound } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import { getSubscriptionAccess } from "@/lib/billing/status";
import { PLANS, getPlan } from "@/lib/billing/plans";
import { BILLING_MANUAL_MODE, BILLING_CONTACT } from "@/lib/billing/config";
import PayButton from "./pay-button";

function formatRupiah(value: number) {
  return `Rp${Math.round(value).toLocaleString("id-ID")}`;
}

const STATUS_LABELS: Record<string, string> = {
  unpaid: "Belum Berlangganan",
  trialing: "Uji Coba",
  active: "Aktif",
  past_due: "Jatuh Tempo",
  expired: "Kedaluwarsa",
};

const STATUS_BADGE: Record<string, string> = {
  unpaid: "bg-zinc-100 text-zinc-600",
  trialing: "bg-brand-50 text-brand-700",
  active: "bg-brand-50 text-brand-700",
  past_due: "bg-amber-50 text-amber-700",
  expired: "bg-red-50 text-red-600",
};

export default async function BillingPage({
  params,
  searchParams,
}: {
  params: Promise<{ businessId: string }>;
  searchParams: Promise<{ status?: string }>;
}) {
  const { businessId } = await params;
  const { status: finishStatus } = await searchParams;
  const supabase = await createClient();

  const { data: business } = await supabase
    .from("businesses")
    .select("id, name")
    .eq("id", businessId)
    .single();

  if (!business) {
    notFound();
  }

  const access = await getSubscriptionAccess(supabase, businessId);
  const currentPlan = access.planCode ? getPlan(access.planCode) : undefined;

  return (
    <div className="mx-auto w-full max-w-2xl px-4 py-10">
      <h1 className="text-lg font-bold text-zinc-900">Langganan — {business.name}</h1>
      <p className="mt-0.5 text-xs text-zinc-500">
        Pilih paket untuk mengaktifkan/memperpanjang akses dashboard &amp; kasir.
      </p>

      {finishStatus === "selesai" && (
        <div className="mt-4 rounded-2xl border border-brand-200 bg-brand-50 p-4 text-sm text-brand-700">
          Terima kasih! Kalau pembayaran berhasil, status di bawah akan berubah otomatis dalam
          beberapa saat (menunggu konfirmasi dari payment gateway).
        </div>
      )}

      <div className="mt-6 rounded-2xl border border-zinc-200 bg-white p-5">
        <div className="flex items-center justify-between">
          <p className="text-xs text-zinc-500">Status Saat Ini</p>
          <span className={`rounded-full px-2.5 py-1 text-xs font-medium ${STATUS_BADGE[access.status]}`}>
            {STATUS_LABELS[access.status]}
          </span>
        </div>
        {currentPlan && (
          <p className="mt-1 text-sm font-semibold text-zinc-900">{currentPlan.name}</p>
        )}
        {access.periodEnd && (
          <p className="mt-0.5 text-xs text-zinc-400">
            {access.status === "past_due" ? "Jatuh tempo sejak" : "Berlaku sampai"}{" "}
            {new Date(access.periodEnd).toLocaleDateString("id-ID", {
              day: "2-digit",
              month: "long",
              year: "numeric",
            })}
          </p>
        )}
        {access.status === "past_due" && (
          <p className="mt-2 text-xs font-medium text-amber-700">
            Segera perpanjang sebelum masa tenggang habis agar akses tidak terkunci.
          </p>
        )}
      </div>

      <div className="mt-8">
        <p className="text-xs font-semibold uppercase tracking-wide text-zinc-400">
          Paket Lengkap — Kasir + Akuntansi
        </p>
        <PlanGrid plans={PLANS.filter((p) => p.family === "full")} businessId={businessId} business={business} />
      </div>

      <div className="mt-8">
        <p className="text-xs font-semibold uppercase tracking-wide text-zinc-400">
          Starter — Kasir + COGS + Laporan Penjualan
        </p>
        <p className="mt-1 text-xs text-zinc-400">
          Paket hemat khusus usaha yang hanya butuh kasir, pantau bahan baku, dan laporan penjualan dasar.
        </p>
        <PlanGrid
          plans={PLANS.filter((p) => p.family === "starter")}
          businessId={businessId}
          business={business}
        />
      </div>

      <div className="mt-8">
        <p className="text-xs font-semibold uppercase tracking-wide text-zinc-400">
          Finance Only — Sudah Punya Kasir Sendiri? Cukup Akuntansi &amp; SDM Saja
        </p>
        <PlanGrid
          plans={PLANS.filter((p) => p.family === "finance")}
          businessId={businessId}
          business={business}
        />
      </div>
    </div>
  );
}

function PlanGrid({
  plans,
  businessId,
  business,
}: {
  plans: typeof PLANS;
  businessId: string;
  business: { name: string };
}) {
  return (
    <div className="mt-2 grid gap-3 sm:grid-cols-3">
      {plans.map((plan) => {
        const message = encodeURIComponent(
          `Halo, saya mau aktivasi paket ${plan.name} untuk toko "${business.name}" di KasirKu.`,
        );
        return (
          <div key={plan.code} className="flex flex-col rounded-2xl border border-zinc-200 bg-white p-5">
            <p className="text-sm font-bold text-zinc-900">{plan.name}</p>
            <p className="mt-1 text-xl font-bold text-brand-700">{formatRupiah(plan.price)}</p>
            <p className="text-[11px] text-zinc-400">
              {plan.kind === "lifetime" ? "Sekali bayar, seterusnya" : `Setiap ${plan.periodDays} hari`}
            </p>
            <div className="mt-4">
              {BILLING_MANUAL_MODE ? (
                <div className="space-y-2">
                  <p className="text-[11px] text-zinc-500">
                    Pembayaran otomatis belum aktif — hubungi kami dulu untuk aktivasi.
                  </p>
                  <a
                    href={`https://wa.me/${BILLING_CONTACT.whatsapp}?text=${message}`}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="block w-full rounded-xl bg-brand-600 py-2.5 text-center text-sm font-semibold text-white transition-colors hover:bg-brand-700"
                  >
                    💬 Chat WhatsApp
                  </a>
                  <a
                    href={`mailto:${BILLING_CONTACT.email}?subject=${encodeURIComponent(
                      `Aktivasi paket ${plan.name} — ${business.name}`,
                    )}&body=${message}`}
                    className="block w-full rounded-xl border border-zinc-200 py-2.5 text-center text-sm font-semibold text-zinc-600 transition-colors hover:bg-zinc-50"
                  >
                    ✉️ Email
                  </a>
                </div>
              ) : (
                <PayButton businessId={businessId} planCode={plan.code} />
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

// Midtrans account is still pending business verification (2026-07-12) — until
// it's approved and a real Sandbox/Production test has succeeded, the
// "Bayar Sekarang" buttons just error out. Flip this back to false once that's
// confirmed working (see [[billing-midtrans]] in project memory); the Midtrans
// integration itself is untouched, this only controls what the billing page
// renders.
export const BILLING_MANUAL_MODE = true;

export const BILLING_CONTACT = {
  whatsapp: "6281234556757",
  email: "create2impact.id@gmail.com",
};

