import type { SupabaseClient } from "@supabase/supabase-js";
import { buildKitchenTicket, type KitchenTicketItem } from "./escpos";

export type KitchenPrintJob = {
  source: string;
  label: string;
  items: (KitchenTicketItem & { category: string | null })[];
  cashierName?: string;
  orderType?: string;
};

// Ticket-building stays server-side (uses Buffer, reads kitchen_printers via
// the caller's Supabase client) — only the actual byte-sending moves to the
// client, since Vercel can never reach a printer's private LAN IP or a
// Bluetooth device, but the cashier's browser/app (physically on the shop's
// network, or physically holding the tablet) can. connectionType tells the
// client which transport to use: print-agent/native-LAN for "lan", the
// native Bluetooth plugin for "bluetooth" (browsers without the plugin can't
// do anything with a bluetooth job — see dispatch-print-jobs.ts).
export type KitchenPrintJobPayload = {
  printerName: string;
  address: string;
  connectionType: "lan" | "bluetooth";
  bytesBase64: string;
};

export async function buildKitchenPrintJobs(
  supabase: SupabaseClient,
  businessId: string,
  job: KitchenPrintJob,
): Promise<KitchenPrintJobPayload[]> {
  if (job.items.length === 0) return [];

  const { data: printers } = await supabase
    .from("kitchen_printers")
    .select("id, name, categories, connection_type, address, prints_receipt")
    .eq("business_id", businessId);

  // A printer marked prints_receipt is the cashier's receipt printer, not a
  // kitchen/bar station — it gets the priced customer receipt automatically
  // instead (see checkout()), so it's excluded here even if its categories
  // would otherwise match every item.
  const addressedPrinters = (printers ?? []).filter(
    (p) => !!p.address && !p.prints_receipt,
  ) as {
    id: string;
    name: string;
    categories: string[];
    connection_type: "lan" | "bluetooth";
    address: string;
  }[];

  const attempts = addressedPrinters
    .map((printer) => {
      const items =
        printer.categories.length > 0
          ? job.items.filter((i) => i.category && printer.categories.includes(i.category))
          : job.items;
      return { printer, items };
    })

export type PosCatalog = {
  products: PosProduct[];
  openBills: PosOpenBill[];
  customers: PosCustomer[];
  customPaymentMethods: string[];
  discountRules: DiscountRule[];
};

// Sumber tunggal data katalog POS (produk/open bill/customer/metode bayar
// custom) — dipakai baik untuk render server pertama kali (pos/page.tsx)
// maupun refresh di background dari client (pos-screen.tsx, lihat
// pos-cache.ts). Sengaja tidak termasuk self_orders — itu sudah punya jalur
// polling sendiri (getSelfOrders di bawah).
export async function getPosCatalog(businessId: string): Promise<PosCatalog> {
  const supabase = await createClient();

  const [{ data: products }, { data: openBillRows }, { data: customers }, { data: customPaymentMethodRows }, { data: discountRuleRows }] =
    await Promise.all([
      supabase
        .from("products")
        .select("id, name, category, price, cost, stock, emoji, barcode, sku, variant_label")
        .eq("business_id", businessId)
        .is("deleted_at", null)
        .order("name", { ascending: true }),
      supabase
        .from("open_bills")
        .select("id, label, items, updated_at")
        .eq("business_id", businessId)
        .order("updated_at", { ascending: false }),
      supabase
        .from("customers")
        .select("id, name, phone")
        .eq("business_id", businessId)
        .is("deleted_at", null)
        .order("name", { ascending: true }),
      supabase
        .from("custom_payment_methods")
        .select("name")
        .eq("business_id", businessId)
        .order("name", { ascending: true }),
      supabase
        .from("discount_rules")
        .select("id, type, product_id, name, value, value_type, active, valid_from, valid_until")
        .eq("business_id", businessId),
    ]);

  return {
    products: (products ?? []) as PosProduct[],
    openBills: (openBillRows ?? []) as unknown as PosOpenBill[],
    customers: customers ?? [],
    customPaymentMethods: (customPaymentMethodRows ?? []).map((m) => m.name),
    discountRules: (discountRuleRows ?? []) as DiscountRule[],
  };
}

