1	import Link from "next/link";
2	import { notFound } from "next/navigation";
3	import { createClient } from "@/lib/supabase/server";
4	
5	const PURCHASE_CATEGORIES = new Set(["Pembelian Bahan Baku", "Pembelian Barang Dagang"]);
6	const REPORT_TIMEZONE = "Asia/Jakarta";
7	
8	function formatRupiah(value: number) {
9	  const sign = value < 0 ? "-" : "";
10	  return `${sign}Rp${Math.round(Math.abs(value)).toLocaleString("id-ID")}`;
11	}
12	
13	function formatRupiahShort(value: number) {
14	  const abs = Math.abs(value);
15	  const sign = value < 0 ? "-" : "";
16	  if (abs >= 1_000_000) return `${sign}Rp${(abs / 1_000_000).toFixed(1)} Jt`;
17	  if (abs >= 1_000) return `${sign}Rp${Math.round(abs / 1_000)} Rb`;
18	  return formatRupiah(value);
19	}
20	
21	function todayStr() {
22	  return new Date().toLocaleDateString("en-CA", { timeZone: REPORT_TIMEZONE });
23	}
24	
25	function monthLabel(monthStr: string) {
26	  return new Date(`${monthStr}-01T00:00:00Z`).toLocaleDateString("id-ID", {
27	    month: "long",
28	    year: "numeric",
29	    timeZone: "UTC",
30	  });
31	}
32	
33	function wibStartOfDay(dateStr: string) {
34	  return `${dateStr}T00:00:00+07:00`;
35	}
36	
37	export default async function BusinessDashboardPage({
38	  params,
39	}: {
40	  params: Promise<{ businessId: string }>;
41	}) {
42	  const { businessId } = await params;
43	  const supabase = await createClient();
44	
45	  const today = todayStr();
46	  const monthStart = `${today.slice(0, 7)}-01`;
47	  const daysSoFar = Number(today.slice(8, 10));
48	
49	  // business, expenses & openShift tidak saling bergantung — paralel.
50	  // transactions menunggu giliran berikutnya karena nama tabelnya
51	  // ditentukan oleh business.business_type.
52	  const [{ data: business }, { data: expenses }, { data: openShift }] = await Promise.all([
53	    supabase.from("businesses").select("id, name, business_type").eq("id", businessId).single(),
54	    supabase
55	      .from("expenses")
56	      .select("date, category, amount")
57	      .eq("business_id", businessId)
58	      .gte("date", monthStart),
59	    supabase
60	      .from("shifts")
61	      .select("id")
62	      .eq("business_id", businessId)
63	      .is("closed_at", null)
64	      .maybeSingle(),
65	  ]);
66	
67	  if (!business) {
68	    notFound();
69	  }
70	
71	  const { data: transactions } = await supabase
72	    .from("transactions")
73	    .select("date, total")
74	    .eq("business_id", businessId)
75	    .eq("voided", false)
76	    .gte("date", wibStartOfDay(monthStart));
77	
78	  const revenue = (transactions ?? []).reduce((s, t) => s + Number(t.total), 0);
79	  const txCount = (transactions ?? []).length;
80	  const totalExpenses = (expenses ?? []).reduce((s, e) => s + Number(e.amount), 0);
81	  const cogs = (expenses ?? [])
82	    .filter((e) => PURCHASE_CATEGORIES.has(e.category))
83	    .reduce((s, e) => s + Number(e.amount), 0);
84	  const operationalExpenses = totalExpenses - cogs;
85	  const netProfit = revenue - totalExpenses;
86	  const margin = revenue > 0 ? Math.round((netProfit / revenue) * 100) : 0;
87	  const marginDisplay = revenue > 0 ? margin : null;
88	  const ringPct = Math.max(0, Math.min(100, margin));
89	
90	  // ── Arus kas harian (pemasukan vs pengeluaran) bulan berjalan ──
91	  const revenueByDay = new Array(daysSoFar).fill(0);
92	  for (const t of transactions ?? []) {
93	    const day = Number(
94	      new Date(t.date).toLocaleString("en-CA", {
95	        timeZone: REPORT_TIMEZONE,
96	        day: "2-digit",
97	      }),
98	    );
99	    if (day >= 1 && day <= daysSoFar) revenueByDay[day - 1] += Number(t.total);
100	  }
101	  const expenseByDay = new Array(daysSoFar).fill(0);
102	  for (const e of expenses ?? []) {
103	    const day = Number(e.date.slice(8, 10));
104	    if (day >= 1 && day <= daysSoFar) expenseByDay[day - 1] += Number(e.amount);
105	  }
106	
107	  const chartW = 640;
108	  const chartH = 180;
109	  const maxVal = Math.max(...revenueByDay, ...expenseByDay, 1);
110	  const stepX = daysSoFar > 1 ? chartW / (daysSoFar - 1) : 0;
111	  const toPoints = (arr: number[]) =>
112	    arr
113	      .map((v, i) => `${Math.round(i * stepX)},${Math.round(chartH - (v / maxVal) * chartH)}`)
114	      .join(" ");
115	  const revenuePoints = toPoints(revenueByDay);
116	  const expensePoints = toPoints(expenseByDay);
117	
118	  return (
119	    <div className="w-full">
120	      <div className="flex flex-wrap items-center justify-between gap-2">
121	        <div>
122	          <h1 className="text-lg font-bold text-zinc-900">Dashboard</h1>
123	          <p className="mt-0.5 text-xs text-zinc-500">
124	            Ringkasan keuangan — {monthLabel(today.slice(0, 7))}
125	          </p>
126	        </div>
127	        {openShift && (
128	          <span className="rounded-full bg-brand-50 px-2.5 py-1 text-[11px] font-semibold text-brand-700">
129	            ● Shift aktif
130	          </span>
131	        )}
132	      </div>
133	
134	      {/* Stat cards */}
135	      <div className="mt-6 grid grid-cols-2 gap-3 lg:grid-cols-4">
136	        <div className="rounded-xl bg-white shadow-sm p-4">
137	          <p className="mb-1.5 text-[10.5px] font-semibold uppercase text-zinc-400">
138	            Total Pendapatan
139	          </p>
140	          <p className="text-xl font-bold text-zinc-900">{formatRupiahShort(revenue)}</p>
141	          <p className="mt-0.5 text-[10.5px] text-zinc-400">{monthLabel(today.slice(0, 7))}</p>
142	        </div>
143	        <div className="rounded-xl bg-white shadow-sm p-4">
