/**
 * Generate shapefile EPSG:3857 (Mercator Auxiliary Sphere) untuk upload OSS.
 * Jalankan: node generate-shapefile.js
 * Output: folder shapefile_oss/ berisi 4 file → zip lalu upload ke OSS.
 *
 * Cara dapat koordinat:
 *   1. Buka Google Maps → cari alamat usaha
 *   2. Klik kanan pada lokasi → salin koordinat (lat, lon)
 *   3. Ganti CENTER_LAT & CENTER_LON di bawah
 */

const fs = require("fs");
const path = require("path");

// ================================================================
// GANTI dengan koordinat lokasi usaha (dari Google Maps klik kanan)
const CENTER_LAT = -7.069976;   // lintang  (negatif = selatan)
const CENTER_LON = 110.4279505; // bujur    (positif = timur)
const SIZE_M = 50;              // setengah sisi kotak dalam meter
// ================================================================

function toMercator(lon, lat) {
  const R = 6378137;
  const x = (lon * Math.PI * R) / 180;
  const y = Math.log(Math.tan(Math.PI / 4 + (lat * Math.PI) / 360)) * R;
  return [x, y];
}

const [cx, cy] = toMercator(CENTER_LON, CENTER_LAT);
const d = SIZE_M;
const xMin = cx - d, yMin = cy - d, xMax = cx + d, yMax = cy + d;

const pts = [
  [xMin, yMin],
  [xMin, yMax],
  [xMax, yMax],
  [xMax, yMin],
  [xMin, yMin], // tutup ring
];

// ── SHP ──────────────────────────────────────────────────────────
function buildSHP() {
  const contentBytes = 4 + 32 + 4 + 4 + 4 + 16 * 5; // 128
  const fileBytes = 100 + 8 + contentBytes;           // 236
  const buf = Buffer.alloc(fileBytes, 0);
  let p = 0;

  buf.writeInt32BE(9994, p); p += 4;
  for (let i = 0; i < 5; i++) { p += 4; }            // unused
  buf.writeInt32BE(fileBytes / 2, p); p += 4;         // file length (words)
  buf.writeInt32LE(1000, p); p += 4;                  // version
  buf.writeInt32LE(5, p); p += 4;                     // Polygon
  buf.writeDoubleLE(xMin, p); p += 8;
  buf.writeDoubleLE(yMin, p); p += 8;
  buf.writeDoubleLE(xMax, p); p += 8;
  buf.writeDoubleLE(yMax, p); p += 8;
  for (let i = 0; i < 4; i++) { p += 8; }            // Z/M ranges

  buf.writeInt32BE(1, p); p += 4;                     // record #1
  buf.writeInt32BE(contentBytes / 2, p); p += 4;      // content length (words)

  buf.writeInt32LE(5, p); p += 4;                     // Polygon
  buf.writeDoubleLE(xMin, p); p += 8;
  buf.writeDoubleLE(yMin, p); p += 8;
  buf.writeDoubleLE(xMax, p); p += 8;
  buf.writeDoubleLE(yMax, p); p += 8;
  buf.writeInt32LE(1, p); p += 4;                     // numParts
  buf.writeInt32LE(5, p); p += 4;                     // numPoints
  buf.writeInt32LE(0, p); p += 4;                     // parts[0]
  for (const [x, y] of pts) {
    buf.writeDoubleLE(x, p); p += 8;
    buf.writeDoubleLE(y, p); p += 8;
  }
  return buf;
}

// ── SHX ──────────────────────────────────────────────────────────
function buildSHX() {
  const buf = Buffer.alloc(108, 0);
  let p = 0;
  buf.writeInt32BE(9994, p); p += 4;
  for (let i = 0; i < 5; i++) { p += 4; }
  buf.writeInt32BE(54, p); p += 4;                    // 108/2
  buf.writeInt32LE(1000, p); p += 4;
  buf.writeInt32LE(5, p); p += 4;
  buf.writeDoubleLE(xMin, p); p += 8;
  buf.writeDoubleLE(yMin, p); p += 8;
  buf.writeDoubleLE(xMax, p); p += 8;
  buf.writeDoubleLE(yMax, p); p += 8;
  for (let i = 0; i < 4; i++) { p += 8; }

  buf.writeInt32BE(50, p); p += 4;                    // offset 100/2
  buf.writeInt32BE(64, p); p += 4;                    // 128/2
  return buf;
}

// ── DBF ──────────────────────────────────────────────────────────
function buildDBF() {
  const buf = Buffer.alloc(34, 0);
  buf[0] = 0x03; buf[1] = 26; buf[2] = 8; buf[3] = 3;
  buf.writeInt32LE(1, 4);   // 1 record
  buf.writeInt16LE(33, 8);  // header size
  buf.writeInt16LE(1, 10);  // record size (deletion flag only)
  buf[32] = 0x0d;           // header terminator
  buf[33] = 0x20;           // record: active (space)
  return buf;
}

// ── PRJ ──────────────────────────────────────────────────────────
const PRJ =
  'PROJCS["WGS_1984_Web_Mercator_Auxiliary_Sphere",' +
  'GEOGCS["GCS_WGS_1984",DATUM["D_WGS_1984",SPHEROID["WGS_1984",6378137.0,298.257223563]],' +
  'PRIMEM["Greenwich",0.0],UNIT["Degree",0.0174532925199433]],' +
  'PROJECTION["Mercator_Auxiliary_Sphere"],' +
  'PARAMETER["False_Easting",0.0],PARAMETER["False_Northing",0.0],' +
  'PARAMETER["Central_Meridian",0.0],PARAMETER["Standard_Parallel_1",0.0],' +
  'PARAMETER["Auxiliary_Sphere_Type",0.0],UNIT["Meter",1.0]]';

// ── Tulis ─────────────────────────────────────────────────────────
const outDir = path.join(__dirname, "shapefile_oss");
if (!fs.existsSync(outDir)) fs.mkdirSync(outDir);

fs.writeFileSync(path.join(outDir, "lokasi_usaha.shp"), buildSHP());
fs.writeFileSync(path.join(outDir, "lokasi_usaha.shx"), buildSHX());
fs.writeFileSync(path.join(outDir, "lokasi_usaha.dbf"), buildDBF());
fs.writeFileSync(path.join(outDir, "lokasi_usaha.prj"), PRJ);

console.log("✓ Shapefile berhasil dibuat di folder: shapefile_oss/");
console.log("  lokasi_usaha.shp  lokasi_usaha.shx  lokasi_usaha.dbf  lokasi_usaha.prj");
console.log("\nLangkah selanjutnya:");
console.log("  1. Buka folder shapefile_oss/");
console.log("  2. Pilih semua 4 file → klik kanan → Send to → Compressed (zipped) folder");
console.log("  3. Upload file .zip itu ke OSS");
console.log(`\nKoordinat center (EPSG:3857): X=${cx.toFixed(1)}, Y=${cy.toFixed(1)}`);

