253	export type ImportProductsState = {
254	  error: string | null;
255	  result: { created: number; updated: number; skipped: number; errors: string[] } | null;
256	};
257	
258	// Matches export/route.ts's column order exactly, so a downloaded-then-
259	// re-uploaded file round-trips without edits.
260	const IMPORT_COLUMNS = [
261	  "name",
262	  "category",
263	  "price",
264	  "cost",
265	  "stock",
266	  "minStock",
267	  "barcode",
268	  "sku",
269	  "variantLabel",
270	  "emoji",
271	] as const;
