273	export async function importProducts(
274	  businessId: string,
275	  _prevState: ImportProductsState,
276	  formData: FormData,
277	): Promise<ImportProductsState> {
278	  const file = formData.get("file") as File | null;
279	  if (!file || file.size === 0) {
280	    return { error: "Pilih file CSV dulu.", result: null };
281	  }
282	
283	  const text = await file.text();
284	  const rows = parseCsv(text).filter((r) => r.some((c) => c.trim() !== ""));
285	  if (rows.length < 2) {
286	    return { error: "File CSV kosong atau cuma berisi header.", result: null };
287	  }
288	
289	  const dataRows = rows.slice(1);
290	  const supabase = await createClient();
291	
292	  const { data: existing } = await supabase
293	    .from("products")
294	    .select("id, sku, barcode")
295	    .eq("business_id", businessId)
296	    .is("deleted_at", null);
297	
298	  const bySku = new Map(
299	    (existing ?? []).filter((p) => p.sku).map((p) => [p.sku as string, p.id]),
300	  );
301	  const byBarcode = new Map(
302	    (existing ?? []).filter((p) => p.barcode).map((p) => [p.barcode as string, p.id]),
303	  );
304	
305	  let created = 0;
306	  let updated = 0;
307	  let skipped = 0;
308	  const errors: string[] = [];
309	
310	  for (let i = 0; i < dataRows.length; i++) {
311	    const row = dataRows[i];
312	    const line = i + 2; // +1 for header, +1 for 1-indexing
313	    const get = (col: (typeof IMPORT_COLUMNS)[number]) =>
314	      row[IMPORT_COLUMNS.indexOf(col)]?.trim() || "";
315	
316	    const name = get("name");
317	    if (!name) {
318	      skipped++;
319	      errors.push(`Baris ${line}: nama produk kosong`);
320	      continue;
321	    }
322	    const price = Number(get("price"));
323	    if (get("price") === "" || Number.isNaN(price) || price < 0) {
324	      skipped++;
325	      errors.push(`Baris ${line}: harga jual tidak valid`);
326	      continue;
327	    }
328	    const cost = Number(get("cost")) || 0;
329	    const stock = Number(get("stock")) || 0;
330	    const minStock = Number(get("minStock")) || 0;
331	    const category = get("category") || null;
332	    const barcode = get("barcode") || null;
333	    const sku = get("sku") || null;
334	    const variantLabel = get("variantLabel") || null;
335	    const emoji = get("emoji") || null;
336	
337	    const record = {
338	      name,
339	      category,
340	      price,
341	      cost,
342	      stock,
343	      min_stock: minStock,
344	      barcode,
345	      sku,
346	      variant_label: variantLabel,
347	      emoji,
348	    };
349	
350	    const matchId = (sku && bySku.get(sku)) || (barcode && byBarcode.get(barcode)) || null;
351	
352	    if (matchId) {
353	      const { error } = await supabase
354	        .from("products")
355	        .update(record)
356	        .eq("id", matchId)
357	        .eq("business_id", businessId);
358	      if (error) {
359	        skipped++;
360	        errors.push(`Baris ${line}: ${error.message}`);
361	      } else {
362	        updated++;
363	      }
364	    } else {
365	      const { error } = await supabase
366	        .from("products")
367	        .insert({ business_id: businessId, ...record });
368	      if (error) {
369	        skipped++;
370	        errors.push(`Baris ${line}: ${error.message}`);
371	      } else {
372	        created++;
373	      }
374	    }
375	  }
376	
377	  await logActivity(
378	    supabase,
379	    businessId,
